mapper.sql:
SELECT c.id AS courseClassId, COALESCE(c.name, '') AS courseName, COALESCE(c.community_id, 0) AS communityId, COALESCE(comm_name.name, '') AS communityName, COALESCE(c.instructor_id, 0) AS instructorId, IF(COALESCE(ins.name, '') = '', COALESCE(c.instructor_name, ''), ins.name) AS instructorName, COALESCE(o.order_count, 0) AS orderCount, COALESCE(o.paid_amount, 0) AS paidAmount, COALESCE(o.purchased_lessons, 0) AS purchasedLessons, COALESCE(cons.consumed_lessons, 0) AS consumedLessons, COALESCE(att.attended_students, 0) AS attendedStudents, COALESCE(att.attended_lessons, 0) AS attendedLessons FROM la_course_class c LEFT JOIN ( SELECT o1.course_class_id, COUNT(*) AS order_count, SUM(o1.order_amount) AS paid_amount, SUM(COALESCE(o1.lesson_count, 0)) AS purchased_lessons FROM la_recharge_order o1 WHERE o1.pay_status = 1 AND o1.delete_time IS NULL AND (o1.refund_status <> 1 OR o1.refund_status IS NULL) AND o1.pay_time BETWEEN #{q.startEpoch} AND #{q.endEpoch} GROUP BY o1.course_class_id ) o ON o.course_class_id = c.id LEFT JOIN ( SELECT cons1.course_class_id, COUNT(*) AS consumed_lessons FROM la_course_consume_log cons1 WHERE cons1.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch} GROUP BY cons1.course_class_id ) cons ON cons.course_class_id = c.id LEFT JOIN ( SELECT b.course_class_id, COUNT(*) AS attended_students, COUNT(DISTINCT CASE WHEN b.lesson_id > 0 THEN b.lesson_id END) AS attended_lessons FROM la_course_booking b WHERE b.status = 10 AND b.lesson_date BETWEEN #{q.startDate} AND #{q.endDate} GROUP BY b.course_class_id ) att ON att.course_class_id = c.id LEFT JOIN la_community comm_name ON comm_name.id = c.community_id AND comm_name.delete_time IS NULL LEFT JOIN la_instructor ins ON ins.id = c.instructor_id AND ins.delete_time IS NULL WHERE c.is_delete = 0 AND (COALESCE(o.order_count, 0) > 0 OR COALESCE(cons.consumed_lessons, 0) > 0 OR COALESCE(att.attended_students, 0) > 0)
AND c.community_id = #{q.communityId}
AND c.id = #{q.courseId}
AND c.instructor_id = #{q.instructorId}
AND (LOWER(COALESCE(c.name, '')) LIKE #{q.keyword} OR LOWER(COALESCE(comm_name.name, '')) LIKE #{q.keyword} OR LOWER(IF(COALESCE(ins.name, '') = '', COALESCE(c.instructor_name, ''), ins.name)) LIKE #{q.keyword})

mapper.select:
SELECT t.* FROM (

) t
ORDER BY t.paidAmount DESC, t.courseClassId ASC
LIMIT #{q.offset}, #{q.limit}

SELECT t.* FROM (

) t
ORDER BY t.paidAmount DESC, t.coachId ASC
LIMIT #{q.offset}, #{q.limit}

mapper.sql:
FROM la_course_consume_log l
JOIN la_course_class c ON c.id = l.course_class_id AND c.is_delete = 0
LEFT JOIN la_community comm ON comm.id = c.community_id AND comm.delete_time IS NULL
LEFT JOIN la_instructor ins ON ins.id = c.instructor_id AND ins.delete_time IS NULL
LEFT JOIN la_user u ON u.id = l.user_id
LEFT JOIN la_student st ON st.id = l.student_id
WHERE l.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}

    AND 1 = 0


    AND c.community_id = #{q.communityId}


    AND l.course_class_id = #{q.courseId}


    AND c.instructor_id = #{q.instructorId}


    AND COALESCE(l.source_type, 0) = #{q.sourceType}


    AND EXISTS (SELECT 1 FROM la_course_booking b
                WHERE b.user_id = l.user_id AND b.student_id = l.student_id
                  AND b.course_class_id = l.course_class_id AND b.lesson_no = l.lesson_no
                  AND b.status = 10)


    AND EXISTS (SELECT 1 FROM la_course_booking b
                WHERE b.user_id = l.user_id AND b.student_id = l.student_id
                  AND b.course_class_id = l.course_class_id AND b.lesson_no = l.lesson_no)
    AND NOT EXISTS (SELECT 1 FROM la_course_booking b
                WHERE b.user_id = l.user_id AND b.student_id = l.student_id
                  AND b.course_class_id = l.course_class_id AND b.lesson_no = l.lesson_no
                  AND b.status = 10)


    AND NOT EXISTS (SELECT 1 FROM la_course_booking b
                WHERE b.user_id = l.user_id AND b.student_id = l.student_id
                  AND b.course_class_id = l.course_class_id AND b.lesson_no = l.lesson_no)


    AND (LOWER(COALESCE(c.name, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(comm.name, '')) LIKE #{q.keyword}
         OR LOWER(IF(COALESCE(ins.name, '') = '', COALESCE(c.instructor_name, ''), ins.name)) LIKE #{q.keyword}
         OR LOWER(COALESCE(st.name, '')) LIKE #{q.keyword}
         OR LOWER(IF(COALESCE(u.real_name, '') = '', COALESCE(u.nickname, ''), u.real_name)) LIKE #{q.keyword}
         OR LOWER(COALESCE(u.mobile, '')) LIKE #{q.keyword})

mapper.select:
SELECT l.id

ORDER BY l.create_time DESC, l.id DESC
LIMIT #{q.offset}, #{q.limit}

mapper.sql:
FROM la_coupon_flow f
LEFT JOIN la_coupon_instance ci ON ci.id = f.coupon_id
LEFT JOIN la_coupon_goods g ON g.id = ci.goods_id
LEFT JOIN la_user u ON u.id = f.user_id
LEFT JOIN la_student st ON st.id = f.student_id
WHERE f.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}

    AND 1 = 0


    AND f.type = #{q.flowType}


    AND ci.goods_id = #{q.couponGoodsId}


    AND f.user_id = #{q.userId}


    AND u.mobile LIKE #{q.mobile}


    AND (LOWER(COALESCE(ci.sn, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(ci.title, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(g.title, ci.title, '')) LIKE #{q.keyword}
         OR LOWER(IF(COALESCE(u.real_name, '') = '', COALESCE(u.nickname, ''), u.real_name)) LIKE #{q.keyword}
         OR LOWER(COALESCE(st.name, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(f.order_sn, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(f.remark, '')) LIKE #{q.keyword})

mapper.select:
SELECT f.id

ORDER BY f.create_time DESC, f.id DESC
LIMIT #{q.offset}, #{q.limit}

mapper.sql:
FROM la_activity_signup s
LEFT JOIN la_activity a ON a.id = s.activity_id
LEFT JOIN la_area ar ON ar.id = a.area_id
LEFT JOIN la_community comm ON comm.id = ar.community_id AND comm.delete_time IS NULL
LEFT JOIN la_recharge_order o ON o.id = s.order_id
LEFT JOIN la_user u ON u.id = s.user_id
LEFT JOIN la_student st ON st.id = s.student_id
WHERE s.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}

    AND 1 = 0


    AND s.activity_id = #{q.activityId}


    AND COALESCE(ar.community_id, 0) = #{q.communityId}


    AND COALESCE(s.status, 0) = #{q.signupStatus}


    AND (LOWER(COALESCE(a.title, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(a.place, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(ar.name, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(comm.name, '')) LIKE #{q.keyword}
         OR LOWER(IF(COALESCE(u.real_name, '') = '', COALESCE(u.nickname, ''), u.real_name)) LIKE #{q.keyword}
         OR LOWER(COALESCE(u.mobile, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(st.name, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(o.sn, '')) LIKE #{q.keyword})

mapper.select:
SELECT s.id

ORDER BY s.create_time DESC, s.id DESC
LIMIT #{q.offset}, #{q.limit}

mapper.sql:
FROM la_class_apply a
LEFT JOIN la_class_apply_group g ON g.id = a.group_id
LEFT JOIN la_region r ON r.id = g.street_id AND r.level = 3
LEFT JOIN la_user u ON u.id = a.user_id
LEFT JOIN la_student st ON st.id = a.student_id
WHERE a.delete_time IS NULL
  AND a.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}

    AND 1 = 0


    AND g.street_id = #{q.streetId}


    AND g.course_type = #{q.courseType}


    AND (CASE WHEN g.id IS NOT NULL THEN COALESCE(g.status, '') ELSE COALESCE(a.status, '') END) = #{q.groupStatus}


    AND (LOWER(COALESCE(r.name, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(g.course_type, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(a.area_name, '')) LIKE #{q.keyword}
         OR LOWER(IF(COALESCE(u.real_name, '') = '', COALESCE(u.nickname, ''), u.real_name)) LIKE #{q.keyword}
         OR LOWER(COALESCE(u.mobile, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(st.name, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(a.phone, '')) LIKE #{q.keyword}
         OR LOWER(COALESCE(a.note, '')) LIKE #{q.keyword})

mapper.select:
SELECT a.id

ORDER BY a.create_time DESC, a.id DESC
LIMIT #{q.offset}, #{q.limit}
